import React from 'react';
import './image.css';

class Switcher extends React.Component {
  constructor(props) {
    super(props);

    const baseUrl = `${props.base_url}api/keyed_image/slideshow/?id=`;
    const initialTokIdx = props.image_ids.length > 1 ? 1 : 0;

    // Each slot ('tik' / 'tok') tracks WHICH INDEX it currently holds,
    // not just a URL. This is what lets us reliably tell "is the image
    // I want already sitting in a buffer?" instead of guessing from URL
    // string equality (which was the root of the ordering bug).
    this.state = {
      currentIndex: 0,
      activeSlot: 'tik', // which slot is currently visible
      slots: {
        tik: { index: 0, url: this.buildUrl(baseUrl, props.image_ids[0], props.img_access_key) },
        tok: { index: initialTokIdx, url: this.buildUrl(baseUrl, props.image_ids[initialTokIdx], props.img_access_key) },
      },
      isLoading: false,
      isIdle: false,
    };

    this.idleTimer = null;
    this.interval = null;
    // Monotonically increasing token. Any in-flight image load whose
    // token doesn't match the latest one when it finishes is stale and
    // gets ignored, instead of being allowed to clobber newer state.
    this.loadToken = 0;

    // DIAGNOSTIC: unique ID per mounted instance, so we can tell from
    // the console whether more than one Switcher is actually mounted.
    this.instanceId = Math.random().toString(36).slice(2, 8);
    console.log(`[Switcher] NEW INSTANCE CONSTRUCTED: ${this.instanceId}`);
  }

  buildUrl(baseUrl, id, accessKey) {
    if (!id) return '';
    return `${baseUrl}${id}&access_key=${accessKey}`;
  }

  resetIdleTimer = () => {
    if (this.state.isIdle) this.setState({ isIdle: false });
    clearTimeout(this.idleTimer);
    this.idleTimer = setTimeout(() => {
      this.setState({ isIdle: true });
    }, 10000);
  };

  // Locks in the requested index and asks the crossfade machinery to
  // make it visible, however many steps away it is from what's cached.
  goToIndex = (targetIndex) => {
    const { image_ids } = this.props;
    if (!image_ids || targetIndex < 0 || targetIndex >= image_ids.length) return;

    console.log(
      `[Switcher ${this.instanceId}] goToIndex(${targetIndex}) called. Current state before:`,
      JSON.parse(JSON.stringify(this.state))
    );

    // Reset timers so manual navigation dictates the pace.
    this.resetTimer();
    this.resetIdleTimer();

    this.setState({ currentIndex: targetIndex }, () => {
      this.showIndex(targetIndex);
    });
  };

  // Figures out whether targetIndex is already visible, already cached
  // in the hidden buffer, or needs to be preloaded - based on the index
  // each slot holds, not on comparing URL strings.
  //
  // Deliberately reads this.state directly and calls setState with a
  // plain object here, rather than doing this inside a setState
  // updater function. Updater functions are not a safe place for side
  // effects (starting an image download, bumping this.loadToken)
  // because React (in StrictMode, and potentially in concurrent
  // rendering) can invoke an updater more than once to verify it's
  // pure - which would have silently kicked off two competing
  // preloads with two different tokens per click.
  showIndex = (targetIndex) => {
    const { image_ids, base_url, img_access_key } = this.props;
    const baseUrl = `${base_url}api/keyed_image/slideshow/?id=`;
    const targetUrl = this.buildUrl(baseUrl, image_ids[targetIndex], img_access_key);

    const { activeSlot, slots } = this.state;
    const inactiveSlot = activeSlot === 'tik' ? 'tok' : 'tik';

    console.log(
      `[Switcher] showIndex(${targetIndex}). activeSlot=${activeSlot} (idx ${slots[activeSlot].index}), inactiveSlot=${inactiveSlot} (idx ${slots[inactiveSlot].index})`
    );

    if (slots[activeSlot].index === targetIndex) {
      // Already looking at it; nothing to do.
      console.log('[Switcher] -> already visible, no-op');
      return;
    }

    if (slots[inactiveSlot].index === targetIndex) {
      // Already sitting in the hidden buffer - flip instantly.
      console.log('[Switcher] -> cache hit, flipping active slot to', inactiveSlot);
      this.setState({ activeSlot: inactiveSlot, isLoading: false });
      return;
    }

    // Not cached anywhere - kick off a background load into the hidden
    // slot. Bump the token so any earlier in-flight load becomes stale
    // and won't be applied once this one wins.
    this.loadToken += 1;
    const requestToken = this.loadToken;
    console.log(`[Switcher] -> cache miss, preloading idx ${targetIndex} into ${inactiveSlot}, token=${requestToken}`);
    this.setState({ isLoading: true });
    this.preloadInto(inactiveSlot, targetIndex, targetUrl, requestToken);
  };

  // Downloads targetUrl in the background, then (if still relevant)
  // writes it into slotName and flips that slot to active.
  preloadInto = (slotName, targetIndex, targetUrl, requestToken) => {
    const img = new window.Image();

    img.onload = () => {
      // A newer navigation superseded this request - drop it on the
      // floor instead of letting it overwrite newer state.
      if (requestToken !== this.loadToken) {
        console.log(`[Switcher] preload for idx ${targetIndex} (token ${requestToken}) resolved but is stale (current token ${this.loadToken}) - discarding`);
        return;
      }
      console.log(`[Switcher] preload for idx ${targetIndex} (token ${requestToken}) landed, activating slot ${slotName}`);

      this.setState(
        (prevState) => ({
          slots: {
            ...prevState.slots,
            [slotName]: { index: targetIndex, url: targetUrl },
          },
          activeSlot: slotName,
          isLoading: false,
        }),
        () => {
          // If the user has already clicked on to a different index
          // while this load was in flight, chase it now instead of
          // leaving the wrong image on screen.
          if (this.state.currentIndex !== targetIndex) {
            this.showIndex(this.state.currentIndex);
          }
        }
      );
    };

    img.onerror = () => {
      if (requestToken !== this.loadToken) return;
      // Unlock the UI if the network request fails so we don't get stuck.
      this.setState({ isLoading: false });
    };

    img.src = targetUrl;
  };

  handlePrev = () => {
    if (this.state.currentIndex > 0) {
      this.goToIndex(this.state.currentIndex - 1);
    }
  };

  handleNext = () => {
    const { image_ids } = this.props;
    if (image_ids && this.state.currentIndex < image_ids.length - 1) {
      this.goToIndex(this.state.currentIndex + 1);
    }
  };

  tick() {
    const { image_ids } = this.props;
    if (!image_ids || image_ids.length <= 1) return;

    // Auto-tick ALWAYS marches forward from whatever the current index
    // is - regardless of whether the user was just navigating forward
    // or backward. So "back to 3, then idle" advances to 4 next, and
    // "forward to 7, then idle" advances to 8 next.
    const nextIdx = (this.state.currentIndex + 1) % image_ids.length;
    this.goToIndex(nextIdx);
  }

  resetTimer() {
    if (this.interval) clearInterval(this.interval);
    if (this.props.image_ids && this.props.image_ids.length > 0) {
      this.interval = setInterval(() => this.tick(), this.props.slide_len * 1000);
    }
  }

  componentDidMount() {
    console.log(`[Switcher ${this.instanceId}] MOUNTED`);
    window.addEventListener('keydown', this.handleKeyDown);
    window.addEventListener('mousemove', this.resetIdleTimer);
    this.resetTimer();
    this.resetIdleTimer();
  }

  componentWillUnmount() {
    console.log(`[Switcher ${this.instanceId}] UNMOUNTED`);
    window.removeEventListener('keydown', this.handleKeyDown);
    window.removeEventListener('mousemove', this.resetIdleTimer);
    if (this.interval) clearInterval(this.interval);
    clearTimeout(this.idleTimer);
  }

  handleKeyDown = (event) => {
    if (event.key === 'ArrowLeft') this.handlePrev();
    else if (event.key === 'ArrowRight') this.handleNext();
  };

  render() {
    const { image_ids } = this.props;
    const { currentIndex, isIdle, activeSlot, slots } = this.state;
    const durationCss = { transitionDuration: `${this.props.slide_len}s` };

    const isFirst = currentIndex === 0;
    const isLast = !image_ids || currentIndex >= image_ids.length - 1;
    const tikVisible = activeSlot === 'tik';

    return (
      <div className={`slideshow-wrapper ${isIdle ? 'idle-cursor' : ''}`}>

        <div
          style={{
            position: 'fixed',
            top: 10,
            left: 10,
            zIndex: 9999,
            background: 'rgba(0,0,0,0.75)',
            color: '#0f0',
            fontFamily: 'monospace',
            fontSize: '18px',
            padding: '8px 12px',
            pointerEvents: 'none',
          }}
        >
          currentIndex: {currentIndex} | id: {image_ids && image_ids[currentIndex]} | activeSlot: {activeSlot} ({slots[activeSlot].index})
        </div>

        {!isFirst && !isIdle && (
          <div className="nav-hit-area nav-left" onClick={this.handlePrev}>
            <div className="nav-icon">&#10094;</div>
          </div>
        )}

        <div className="mask">
          <div className="pic-wrapper">
            <img
              className={tikVisible ? 'visible' : 'hidden'}
              src={slots.tik.url}
              alt=""
              style={durationCss}
            />
            <img
              className={tikVisible ? 'hidden' : 'visible'}
              src={slots.tok.url}
              alt=""
              style={durationCss}
            />
          </div>
        </div>

        {!isLast && !isIdle && (
          <div className="nav-hit-area nav-right" onClick={this.handleNext}>
            <div className="nav-icon">&#10095;</div>
          </div>
        )}
      </div>
    );
  }
}

export default Switcher;